-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $alitas$
DECLARE
 j constant jsonb := $records$[{"id":"2d31cabb-b350-4c6f-a444-eec6b03c28eb","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"alitas-bbq","public_path":"/alitas-bbq","source_url":"https://manualdecocina.com/alitas-bbq/","language":"es","title":"Alitas BBQ al horno con salsa de tomate","excerpt":"Alitas al horno glaseadas al final con salsa BBQ de tomate. Cuatro raciones propuestas, temperatura de seguridad y nutrición estimada con huesos separados.","summary":"Alitas al horno con un glaseado BBQ de tomate, azúcar moreno, vinagre y pimentón ahumado aplicado al final. Se proponen cuatro raciones y 65 minutos, con comprobación de 74 °C en el pollo. Fórmula, rendimiento y tiempos pendientes de prueba de cocina.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Fácil","course":"Plato principal","cuisine":"Inspiración estadounidense","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"alitas de pollo crudas con piel y hueso, partidas, sin puntas","amount":"1000","unit":"g","group":"Alitas"},{"name":"aceite de oliva","amount":"10","unit":"g","group":"Alitas"},{"name":"sal fina","amount":"3","unit":"g","group":"Alitas"},{"name":"pimienta negra molida","amount":"1","unit":"g","group":"Alitas"},{"name":"kétchup de tomate","amount":"160","unit":"g","group":"Salsa BBQ"},{"name":"azúcar moreno","amount":"25","unit":"g","group":"Salsa BBQ"},{"name":"vinagre de sidra","amount":"25","unit":"g","group":"Salsa BBQ"},{"name":"salsa Worcestershire","amount":"10","unit":"g","group":"Salsa BBQ"},{"name":"ajo pelado y muy picado","amount":"8","unit":"g","group":"Salsa BBQ"},{"name":"pimentón dulce ahumado","amount":"2","unit":"g","group":"Salsa BBQ"},{"name":"agua potable","amount":"40","unit":"g","group":"Salsa BBQ"}],"steps":[{"title":"Precalienta y prepara las alitas","content":"Precalienta el horno a 220 °C, calor arriba y abajo, durante unos 15 minutos mientras preparas los ingredientes; ese precalentado se solapa con los 20 minutos de preparación propuestos. Usa 1000 g de alitas crudas partidas, con piel y hueso y sin puntas, descongeladas en refrigeración si procede. No laves el pollo. Seca con papel desechable sin salpicar, retíralo y lava manos y superficies. Coloca una rejilla apta para horno dentro de una bandeja metálica profunda de unos 40 × 30 cm, con aluminio debajo para recoger los jugos. Mantén el pollo separado de la salsa y de los utensilios limpios.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"Alitas BBQ: Precalienta y prepara las alitas"},{"title":"Sazona y distribuye sin amontonar","content":"Mezcla las alitas con 10 g de aceite de oliva, 3 g de sal y 1 g de pimienta negra en un cuenco reservado para pollo crudo. Distribuye en una sola capa sobre la rejilla, dejando un pequeño espacio entre piezas. No añadas todavía la salsa dulce. Si no caben sin amontonarse, usa otra bandeja y registra el efecto sobre el tiempo; evita acercarlas a la resistencia superior. Limpia el cuenco y los utensilios del crudo antes de usarlos para servir.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"Alitas BBQ: Sazona y distribuye sin amontonar"},{"title":"Hornea la primera cara","content":"Introduce la bandeja en la zona central del horno y hornea las alitas unos 20 minutos a 220 °C. La piel empieza a dorarse y los jugos caen a la bandeja, pero aún no se consideran listas para comer. No te guíes solo por el color. Durante este tramo prepara la salsa en un cazo separado, sin contacto con el pollo crudo.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"Alitas BBQ: Hornea la primera cara"},{"title":"Cocina una salsa BBQ de tomate","content":"Pon en un cazo limpio 160 g de kétchup, 25 g de azúcar moreno, 25 g de vinagre de sidra, 10 g de salsa Worcestershire, 8 g de ajo muy picado, 2 g de pimentón dulce ahumado y 40 g de agua. Remueve, calienta hasta pequeñas burbujas y cocina suavemente unos 8 minutos, moviendo para disolver el azúcar y evitar que se pegue. Debe cubrir la cuchara, sin convertirse en caramelo. Esta cocción se hace durante el horneado y no se suma otra vez al total. Aparta aproximadamente la mitad en un recipiente limpio para servir y la otra mitad para pincelar; no devuelvas el pincel al recipiente de servicio.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"Alitas BBQ: Cocina una salsa BBQ de tomate"},{"title":"Gira y comprueba el interior","content":"Al terminar los primeros 20 minutos, gira las alitas con pinzas y hornea otros 15 minutos a 220 °C. Mide varias piezas grandes con una sonda limpia en la parte más gruesa de la carne, sin tocar el hueso ni la rejilla: deben alcanzar al menos 74 °C. Si no lo hacen, prolonga el horneado y repite la comprobación antes de glasear. El tamaño de la pieza y el horno cambian el tiempo real; la piel dorada no prueba que esté segura.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"Alitas BBQ: Gira y comprueba el interior"},{"title":"Glasea al final y deja reposar","content":"Con las alitas ya comprobadas a 74 °C, pincela una capa fina de la mitad de salsa destinada a glasear. Devuelve al horno a 220 °C durante unos 5 minutos, vigilando para que el azúcar no se ennegrezca; evita el grill como sustituto de cocción. Comprueba de nuevo al menos 74 °C en piezas gruesas, saca con guantes y deja reposar 5 minutos. Se proponen 40 minutos de horno, más ese reposo, pero cualquier cocción adicional amplía el total. Mantén separada y limpia la salsa reservada para servir.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Alitas BBQ: Glasea al final y deja reposar"},{"title":"Sirve en cuatro raciones","content":"Reparte las alitas calientes en 4 raciones iguales, distribuyendo piezas grandes y pequeñas, y acompaña con la salsa limpia reservada. La propuesta suma 20 minutos de preparación, 40 de horno y 5 de reposo: 65 minutos totales, con el precalentado y la salsa solapados. No se ha ensayado en cocina ni medido el peso final. La nutrición supone 700 g comestibles de carne y piel para los 1000 g con hueso, una hipótesis del 70 % pendiente de confirmar, e incluye toda la salsa y el aceite; no significa que cada ración pese esa cantidad.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Alitas BBQ: Sirve en cuatro raciones"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"alitas de pollo crudas con piel y hueso, partidas, sin puntas","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"aceite de oliva","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"sal fina","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"pimienta negra molida","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"kétchup de tomate","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"azúcar moreno","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"vinagre de sidra","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"salsa Worcestershire","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"ajo pelado y muy picado","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"pimentón dulce ahumado","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"agua potable","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"Una cuarta parte de las alitas y toda la salsa propuesta; 4 raciones sin peso final medido","method":"Suma once cantidades comestibles por sus ocho valores USDA por 100 g y divide entre 4. Para 1000 g de alitas con hueso usa 700 g de carne y piel crudas comestibles, hipótesis del 70 % no medida ni atribuida a USDA. Incluye todo el aceite y la salsa; no descuenta grasa escurrida ni restos.","note":"Estimación de ingredientes, no análisis ni prueba de cocina. La ficha del pollo es carne y piel crudas, sin hueso; la hipótesis comestible está pendiente de confirmación y puede cambiar mucho por pieza. Kétchup y Worcestershire genéricos, pimentón ahumado aproximado mediante paprika genérica. Todas las marcas pueden diferir. No se ha medido el peso cocido ni la salsa consumida. Todos los ocho nutrientes existen en las fichas; no se rellena una ausencia con cero."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Alitas de pollo horneadas con glaseado rojo de salsa BBQ de tomate, junto a un cuenco de salsa"}],"published":true,"editorial_status":"published","keywords":["alitas BBQ","alitas al horno","salsa barbacoa de tomate","alitas glaseadas"],"notes":"Propuesta editorial sin prueba de cocina. Alitas con hueso y piel, sin puntas, ya descongeladas: el tiempo de descongelación no está incluido. Descongela en refrigeración, mantén el pollo a 4 °C o menos y respeta el envase. No laves pollo crudo; evita que sus jugos contacten con alimentos o utensilios limpios. Una sonda en carne gruesa, sin tocar hueso, debe marcar al menos 74 °C; el color no basta. La salsa BBQ es de tomate, vinagre y azúcar moreno, distinta de un glaseado de miel y soja; no se incorpora miel ni soja como ingrediente directo. Worcestershire puede contener pescado, gluten, soja u otros alérgenos según la marca: revisa todas las etiquetas. El ahumado procede del pimentón, no se afirma cocción en barbacoa real. Aplica el azúcar al final para reducir el riesgo de quemarlo, y no amontones las piezas. La cantidad de hueso varía: la nutrición adopta como hipótesis 700 g de carne y piel comestibles de 1000 g con hueso, 70 %, pendiente de confirmar mediante pesaje. Esa fracción no es una cifra USDA ni un rendimiento probado. Se cuentan todo el aceite y la salsa y no se restan grasa escurrida ni restos no consumidos; las cifras pueden sobreestimar lo realmente ingerido. El pimentón ahumado se modela con paprika genérica y las salsas varían por marca. Menos azúcar o una salsa de distinta composición alteran sabor, adherencia y nutrición. Para otra proteína, ajusta cocción y cálculo; no la publiques como alitas de pollo. Refrigera pronto las sobras en recipientes poco profundos a 4 °C o menos y consúmelas en 3–4 días según la guía oficial para pollo cocido. No las dejes fuera más de 2 horas, o 1 hora por encima de 32 °C. Recalienta hasta 74 °C. Se propone congelar porciones tapadas hasta 2 meses como plazo doméstico de calidad, sin ensayo de textura de esta fórmula.","seo":{"title":"Alitas BBQ al horno con salsa de tomate paso a paso","description":"Alitas BBQ con salsa de tomate para cuatro raciones propuestas. Glaseado final, tiempos completos, control de 74 °C y nutrición estimada.","image_alt":"Alitas de pollo horneadas con glaseado rojo de salsa BBQ de tomate, junto a un cuenco de salsa","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"¿Las alitas se cocinan en una barbacoa?","a":"Esta propuesta se cocina en horno a 220 °C. BBQ describe la salsa de tomate, vinagre, azúcar moreno y pimentón ahumado. No se afirma que se hayan ahumado ni cocinado sobre brasas."},{"q":"¿Cuándo añado la salsa y cómo sé que el pollo está listo?","a":"Comprueba primero al menos 74 °C dentro de varias piezas grandes, sin tocar hueso. Pincela la salsa dulce al final y hornea unos 5 minutos, vigilando que no se queme. El tiempo propuesto no sustituye el termómetro."},{"q":"¿Qué incluye la nutrición y cómo guardo las sobras?","a":"Incluye toda la salsa y el aceite y supone 700 g comestibles para 1000 g con hueso, una fracción del 70 % pendiente de confirmación, no medida. Refrigera pronto a 4 °C o menos, consume en 3–4 días y recalienta a 74 °C. No dejes fuera más de 2 horas, o 1 hora por encima de 32 °C."}]},"content_html":"<p>Alitas al horno con un glaseado BBQ de tomate, azúcar moreno, vinagre y pimentón ahumado aplicado al final. Se proponen cuatro raciones y 65 minutos, con comprobación de 74 °C en el pollo. Fórmula, rendimiento y tiempos pendientes de prueba de cocina.</p><p>Propuesta editorial sin prueba de cocina. Alitas con hueso y piel, sin puntas, ya descongeladas: el tiempo de descongelación no está incluido. Descongela en refrigeración, mantén el pollo a 4 °C o menos y respeta el envase. No laves pollo crudo; evita que sus jugos contacten con alimentos o utensilios limpios. Una sonda en carne gruesa, sin tocar hueso, debe marcar al menos 74 °C; el color no basta. La salsa BBQ es de tomate, vinagre y azúcar moreno, distinta de un glaseado de miel y soja; no se incorpora miel ni soja como ingrediente directo. Worcestershire puede contener pescado, gluten, soja u otros alérgenos según la marca: revisa todas las etiquetas. El ahumado procede del pimentón, no se afirma cocción en barbacoa real. Aplica el azúcar al final para reducir el riesgo de quemarlo, y no amontones las piezas. La cantidad de hueso varía: la nutrición adopta como hipótesis 700 g de carne y piel comestibles de 1000 g con hueso, 70 %, pendiente de confirmar mediante pesaje. Esa fracción no es una cifra USDA ni un rendimiento probado. Se cuentan todo el aceite y la salsa y no se restan grasa escurrida ni restos no consumidos; las cifras pueden sobreestimar lo realmente ingerido. El pimentón ahumado se modela con paprika genérica y las salsas varían por marca. Menos azúcar o una salsa de distinta composición alteran sabor, adherencia y nutrición. Para otra proteína, ajusta cocción y cálculo; no la publiques como alitas de pollo. Refrigera pronto las sobras en recipientes poco profundos a 4 °C o menos y consúmelas en 3–4 días según la guía oficial para pollo cocido. No las dejes fuera más de 2 horas, o 1 hora por encima de 32 °C. Recalienta hasta 74 °C. Se propone congelar porciones tapadas hasta 2 meses como plazo doméstico de calidad, sin ensayo de textura de esta fórmula.</p>"},{"id":"bfb762c1-2d25-5632-9f26-be6ed20066bc","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"bbq-chicken-wings","public_path":"/de/bbq-chicken-wings","source_url":"https://manualdecocina.com/de/bbq-chicken-wings/","language":"de","title":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce","excerpt":"Ofenflügel mit erst zum Schluss aufgetragener Tomaten-BBQ-Glasur. Vier vorgeschlagene Portionen, Temperaturkontrolle und geschätzte Nährwerte ohne Knochengewicht.","summary":"Hähnchenflügel aus dem Ofen mit einer erst zum Schluss aufgetragenen BBQ-Glasur aus Tomaten, braunem Zucker, Essig und geräuchertem Paprika. Vorgeschlagen sind vier Portionen und 65 Minuten, mit Kontrolle von 74 °C im Hähnchen. Rezeptur, Ausbeute und Zeiten sind noch nicht küchenerprobt.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Einfach","course":"Hauptgericht","cuisine":"US-amerikanisch inspiriert","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"Rohe Hähnchenflügel mit Haut und Knochen, geteilt, ohne Spitzen","amount":"1000","unit":"g","group":"Hähnchenflügel"},{"name":"Olivenöl","amount":"10","unit":"g","group":"Hähnchenflügel"},{"name":"Feines Salz","amount":"3","unit":"g","group":"Hähnchenflügel"},{"name":"Gemahlener schwarzer Pfeffer","amount":"1","unit":"g","group":"Hähnchenflügel"},{"name":"Tomatenketchup","amount":"160","unit":"g","group":"BBQ-Sauce"},{"name":"Brauner Zucker","amount":"25","unit":"g","group":"BBQ-Sauce"},{"name":"Apfelessig","amount":"25","unit":"g","group":"BBQ-Sauce"},{"name":"Worcestershiresauce","amount":"10","unit":"g","group":"BBQ-Sauce"},{"name":"Geschälter, sehr fein gehackter Knoblauch","amount":"8","unit":"g","group":"BBQ-Sauce"},{"name":"Geräuchertes edelsüßes Paprikapulver","amount":"2","unit":"g","group":"BBQ-Sauce"},{"name":"Trinkwasser","amount":"40","unit":"g","group":"BBQ-Sauce"}],"steps":[{"title":"Vorheizen und Flügel vorbereiten","content":"Backofen mit Ober- und Unterhitze auf 220 °C vorheizen, ungefähr 15 Minuten während der Vorbereitung. Das Vorheizen überschneidet sich mit den vorgeschlagenen 20 Minuten Vorbereitung. 1000 g geteilte rohe Flügel mit Haut und Knochen ohne Spitzen verwenden, bei Bedarf zuvor im Kühlschrank aufgetaut. Hähnchen nicht waschen. Ohne Spritzer mit Einweg-Küchenpapier trocken tupfen, Papier entsorgen und Hände sowie Flächen reinigen. Ein ofenfestes Gitter in ein tiefes Metallblech von etwa 40 × 30 cm setzen, darunter Alufolie zum Auffangen der Säfte. Hähnchen getrennt von Sauce und sauberen Utensilien halten.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Vorheizen und Flügel vorbereiten"},{"title":"Würzen und ohne Stapeln verteilen","content":"Flügel mit 10 g Olivenöl, 3 g Salz und 1 g schwarzem Pfeffer in einer Schüssel nur für rohes Hähnchen vermischen. In einer Lage mit etwas Abstand auf dem Gitter verteilen. Noch keine süße Sauce auftragen. Falls sie nicht nebeneinander passen, ein weiteres Blech verwenden und den Einfluss auf die Garzeit festhalten. Nicht nahe an die obere Heizspirale schieben. Schüssel und Rohfleischutensilien reinigen, bevor sie zum Servieren verwendet werden.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Würzen und ohne Stapeln verteilen"},{"title":"Erste Seite backen","content":"Blech in der mittleren Ofenzone einschieben und die Flügel etwa 20 Minuten bei 220 °C backen. Die Haut beginnt zu bräunen, Säfte tropfen ins Blech; die Flügel gelten noch nicht als verzehrfertig. Nicht allein nach der Farbe urteilen. Währenddessen die Sauce in einem getrennten Topf ohne Kontakt zu rohem Hähnchen zubereiten.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Erste Seite backen"},{"title":"Tomaten-BBQ-Sauce kochen","content":"In einen sauberen Topf 160 g Ketchup, 25 g braunen Zucker, 25 g Apfelessig, 10 g Worcestershiresauce, 8 g fein gehackten Knoblauch, 2 g geräuchertes edelsüßes Paprikapulver und 40 g Wasser geben. Verrühren, bis zu kleinen Blasen erhitzen und etwa 8 Minuten sanft kochen, dabei Zucker lösen und Ansetzen verhindern. Die Sauce soll einen Löffel überziehen, nicht zu Karamell werden. Sie kocht während des Backens und wird nicht nochmals zur Gesamtzeit addiert. Etwa die Hälfte in einem sauberen Gefäß zum Servieren zurückbehalten, die andere zum Bestreichen verwenden. Den Pinsel nicht in die Serviersauce tauchen.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Tomaten-BBQ-Sauce kochen"},{"title":"Wenden und den Kern prüfen","content":"Nach den ersten 20 Minuten die Flügel mit einer Zange wenden und weitere 15 Minuten bei 220 °C backen. Mehrere große Stücke mit einer sauberen Sonde an der dicksten Fleischstelle messen, ohne Knochen oder Gitter zu berühren: mindestens 74 °C müssen erreicht werden. Andernfalls länger backen und vor dem Glasieren erneut prüfen. Stückgröße und Ofen verändern die tatsächliche Zeit; gebräunte Haut beweist keine Sicherheit.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Wenden und den Kern prüfen"},{"title":"Zum Schluss glasieren und ruhen lassen","content":"Nach bestätigten 74 °C die Flügel dünn mit der zum Glasieren bestimmten Saucenhälfte bestreichen. Bei 220 °C ungefähr 5 Minuten zurück in den Ofen geben und darauf achten, dass der Zucker nicht schwarz wird. Die Grillfunktion ersetzt das Garen nicht. In dicken Stücken nochmals mindestens 74 °C prüfen, mit Ofenhandschuhen herausnehmen und 5 Minuten ruhen lassen. Vorgeschlagen sind 40 Minuten im Ofen plus diese Ruhezeit; weiteres Garen verlängert die Gesamtzeit. Die zurückbehaltene Serviersauce getrennt und sauber halten.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: Zum Schluss glasieren und ruhen lassen"},{"title":"In vier Portionen servieren","content":"Heiße Flügel in 4 gleiche Portionen teilen, große und kleine Stücke verteilen und die saubere zurückbehaltene Sauce dazugeben. Vorgesehen sind 20 Minuten Vorbereitung, 40 Minuten Ofenzeit und 5 Minuten Ruhe: insgesamt 65 Minuten, wobei Vorheizen und Sauce parallel laufen. Es gibt keine Küchenprüfung oder Messung des Endgewichts. Für die Nährwerte werden 700 g essbares Fleisch und Haut aus 1000 g mit Knochen angenommen: eine unbestätigte Hypothese von 70 %. Sämtliche Sauce und Öl sind enthalten; dies ist keine Gewichtsangabe je Portion.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"BBQ-Chicken-Wings aus dem Ofen mit Tomatensauce: In vier Portionen servieren"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Rohe Hähnchenflügel mit Haut und Knochen, geteilt, ohne Spitzen","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"Olivenöl","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"Feines Salz","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Gemahlener schwarzer Pfeffer","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"Tomatenketchup","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"Brauner Zucker","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"Apfelessig","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"Worcestershiresauce","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"Geschälter, sehr fein gehackter Knoblauch","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"Geräuchertes edelsüßes Paprikapulver","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"Trinkwasser","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"Ein Viertel der Flügel und der gesamten vorgeschlagenen Sauce; 4 Portionen ohne gemessenes Endgewicht","method":"Elf essbare Mengen mit je acht USDA-Werten pro 100 g gewichten, summieren und durch 4 teilen. Für 1000 g Flügel mit Knochen werden 700 g rohes Fleisch und Haut angesetzt: ungemessene Hypothese von 70 %, nicht USDA zugeschrieben. Sämtliche Sauce und Öl werden gerechnet, ohne Abzug für Fett oder Reste.","note":"Zutatenschätzung, keine Analyse oder Küchenprüfung. Hähnchendaten gelten für rohes Fleisch und Haut ohne Knochen; der angenommene essbare Anteil ist unbestätigt und stückabhängig. Generischer Ketchup und Worcestershiresauce; Rauchpaprika mit generischem Paprika angenähert. Marken können abweichen. Gargewicht und gegessene Sauce nicht gemessen. Alle acht Nährstoffe sind vorhanden; fehlende Werte werden nicht durch null ersetzt."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Gebackene Hähnchenflügel mit roter Tomaten-BBQ-Glasur neben einer kleinen Schüssel Sauce"}],"published":true,"editorial_status":"published","keywords":["BBQ-Chicken-Wings","Hähnchenflügel im Ofen","Tomaten-BBQ-Sauce","glasierte Flügel"],"notes":"Redaktioneller Vorschlag ohne Küchenprüfung. Geteilte Flügel mit Haut und Knochen ohne Spitzen, bereits aufgetaut; Auftauzeit ist nicht enthalten. Im Kühlschrank auftauen, Hähnchen bei höchstens 4 °C halten und Verpackung beachten. Rohes Hähnchen nicht waschen und Säfte von sauberen Utensilien und Lebensmitteln fernhalten. Saubere Sonde in dickem Fleisch ohne Knochenkontakt: mindestens 74 °C, Farbe reicht nicht. Diese Tomaten-Essig-Zucker-BBQ-Sauce unterscheidet sich von Honig-Soja-Glasur; Honig und Sojasauce werden nicht direkt zugesetzt. Worcestershiresauce kann je nach Marke Fisch, Gluten, Soja oder weitere Allergene enthalten; alle Etiketten prüfen. Raucharoma kommt vom Paprika, tatsächliches Grillen wird nicht behauptet. Zucker erst zum Schluss auftragen und Stücke nicht stapeln. Die Nährwerte setzen 700 g rohes essbares Fleisch und Haut aus 1000 g mit Knochen an, 70 %, noch durch Wiegen zu bestätigen. Das ist weder eine USDA-Ausbeute noch ein gemessenes Ergebnis. Alles Öl und alle Sauce werden gerechnet, ohne Abzug für abgetropftes Fett oder nicht verzehrte Reste; tatsächlich gegessene Mengen können geringer sein. Geräucherter Paprika wird mit generischem Paprika modelliert; Saucen variieren nach Marke. Weniger Zucker oder andere Sauce verändert Geschmack, Haftung und Nährwerte. Andere Proteine benötigen eigene Garzeiten und Berechnungen. Reste zeitnah in flachen Behältern bei höchstens 4 °C kühlen und laut amtlicher Empfehlung für gegartes Hähnchen innerhalb von 3–4 Tagen verzehren. Nicht länger als 2 Stunden ungekühlt, bei über 32 °C höchstens 1 Stunde. Auf 74 °C erhitzen. Bis zu 2 Monate gefroren werden als häuslicher Qualitätsvorschlag angesetzt; die Textur ist nicht erprobt.","seo":{"title":"BBQ-Chicken-Wings im Ofen mit Tomatensauce","description":"Ofenflügel mit Tomaten-BBQ-Sauce für vier vorgeschlagene Portionen. Späte Glasur, vollständige Zeiten, Kontrolle von 74 °C und geschätzte Nährwerte.","image_alt":"Gebackene Hähnchenflügel mit roter Tomaten-BBQ-Glasur neben einer kleinen Schüssel Sauce","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"Werden die Flügel auf einem Grill gegart?","a":"Dieser Vorschlag nutzt einen Ofen bei 220 °C. BBQ bezeichnet die Sauce aus Tomaten, Essig, braunem Zucker und geräuchertem Paprika. Räuchern oder Garen über Kohlen wird nicht behauptet."},{"q":"Wann kommt die Sauce hinzu und wann ist das Hähnchen sicher?","a":"Zuerst mindestens 74 °C im Inneren mehrerer großer Stücke ohne Knochenkontakt prüfen. Süße Sauce zum Schluss aufpinseln und etwa 5 Minuten backen, ohne sie zu verbrennen. Die vorgeschlagene Zeit ersetzt kein Thermometer."},{"q":"Was enthalten die Nährwerte und wie lagere ich Reste?","a":"Sämtliche Sauce und Öl sind enthalten; aus 1000 g mit Knochen werden 700 g essbarer Anteil angenommen, eine ungemessene und unbestätigte Hypothese von 70 %. Zeitnah bei höchstens 4 °C kühlen, innerhalb von 3–4 Tagen essen und auf 74 °C erhitzen. Höchstens 2 Stunden draußen lassen, bei über 32 °C höchstens 1 Stunde."}]},"content_html":"<p>Hähnchenflügel aus dem Ofen mit einer erst zum Schluss aufgetragenen BBQ-Glasur aus Tomaten, braunem Zucker, Essig und geräuchertem Paprika. Vorgeschlagen sind vier Portionen und 65 Minuten, mit Kontrolle von 74 °C im Hähnchen. Rezeptur, Ausbeute und Zeiten sind noch nicht küchenerprobt.</p><p>Redaktioneller Vorschlag ohne Küchenprüfung. Geteilte Flügel mit Haut und Knochen ohne Spitzen, bereits aufgetaut; Auftauzeit ist nicht enthalten. Im Kühlschrank auftauen, Hähnchen bei höchstens 4 °C halten und Verpackung beachten. Rohes Hähnchen nicht waschen und Säfte von sauberen Utensilien und Lebensmitteln fernhalten. Saubere Sonde in dickem Fleisch ohne Knochenkontakt: mindestens 74 °C, Farbe reicht nicht. Diese Tomaten-Essig-Zucker-BBQ-Sauce unterscheidet sich von Honig-Soja-Glasur; Honig und Sojasauce werden nicht direkt zugesetzt. Worcestershiresauce kann je nach Marke Fisch, Gluten, Soja oder weitere Allergene enthalten; alle Etiketten prüfen. Raucharoma kommt vom Paprika, tatsächliches Grillen wird nicht behauptet. Zucker erst zum Schluss auftragen und Stücke nicht stapeln. Die Nährwerte setzen 700 g rohes essbares Fleisch und Haut aus 1000 g mit Knochen an, 70 %, noch durch Wiegen zu bestätigen. Das ist weder eine USDA-Ausbeute noch ein gemessenes Ergebnis. Alles Öl und alle Sauce werden gerechnet, ohne Abzug für abgetropftes Fett oder nicht verzehrte Reste; tatsächlich gegessene Mengen können geringer sein. Geräucherter Paprika wird mit generischem Paprika modelliert; Saucen variieren nach Marke. Weniger Zucker oder andere Sauce verändert Geschmack, Haftung und Nährwerte. Andere Proteine benötigen eigene Garzeiten und Berechnungen. Reste zeitnah in flachen Behältern bei höchstens 4 °C kühlen und laut amtlicher Empfehlung für gegartes Hähnchen innerhalb von 3–4 Tagen verzehren. Nicht länger als 2 Stunden ungekühlt, bei über 32 °C höchstens 1 Stunde. Auf 74 °C erhitzen. Bis zu 2 Monate gefroren werden als häuslicher Qualitätsvorschlag angesetzt; die Textur ist nicht erprobt.</p>"},{"id":"dd546257-ea19-5bcc-b912-68c626c3d892","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"bbq-chicken-wings","public_path":"/en/bbq-chicken-wings","source_url":"https://manualdecocina.com/en/bbq-chicken-wings/","language":"en","title":"Oven BBQ chicken wings with tomato sauce","excerpt":"Oven wings glazed at the end with tomato BBQ sauce. Four proposed servings, safe-temperature checks and estimated nutrition with bones excluded.","summary":"Oven chicken wings with a late-applied BBQ glaze of tomato, brown sugar, vinegar and smoked paprika. Four servings and 65 minutes are proposed, with a 74 °C temperature check in the chicken. Formula, yield and timings await kitchen testing.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Easy","course":"Main dish","cuisine":"American inspired","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"Raw chicken wing sections with skin and bone, tips removed","amount":"1000","unit":"g","group":"Wings"},{"name":"Olive oil","amount":"10","unit":"g","group":"Wings"},{"name":"Fine salt","amount":"3","unit":"g","group":"Wings"},{"name":"Ground black pepper","amount":"1","unit":"g","group":"Wings"},{"name":"Tomato ketchup","amount":"160","unit":"g","group":"BBQ sauce"},{"name":"Brown sugar","amount":"25","unit":"g","group":"BBQ sauce"},{"name":"Cider vinegar","amount":"25","unit":"g","group":"BBQ sauce"},{"name":"Worcestershire sauce","amount":"10","unit":"g","group":"BBQ sauce"},{"name":"Peeled, very finely chopped garlic","amount":"8","unit":"g","group":"BBQ sauce"},{"name":"Sweet smoked paprika","amount":"2","unit":"g","group":"BBQ sauce"},{"name":"Drinking water","amount":"40","unit":"g","group":"BBQ sauce"}],"steps":[{"title":"Preheat and prepare the wings","content":"Preheat the oven to 220 °C with conventional top and bottom heat for about 15 minutes while preparing ingredients. Preheating overlaps the proposed 20 minutes of preparation. Use 1000 g raw split wings with skin and bone, without tips, thawed in the refrigerator beforehand if needed. Do not wash chicken. Pat dry with disposable paper towel without splashing, discard the towel and wash hands and surfaces. Fit an oven-safe rack inside a deep metal baking tray about 40 × 30 cm, with foil underneath to collect juices. Keep chicken separate from the sauce and clean utensils.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Preheat and prepare the wings"},{"title":"Season and space out","content":"Mix the wings with 10 g olive oil, 3 g salt and 1 g black pepper in a bowl reserved for raw chicken. Arrange in a single layer on the rack with a little space between pieces. Do not add the sweet sauce yet. If they will not fit without crowding, use another tray and record the timing effect; keep them away from the upper heating element. Clean the raw-chicken bowl and utensils before using them for serving.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Season and space out"},{"title":"Bake the first side","content":"Put the tray in the middle of the oven and bake the wings for about 20 minutes at 220 °C. Skin starts browning and juices drip into the tray, but the wings are not yet considered ready to eat. Do not judge by colour alone. During this interval prepare the sauce in a separate saucepan without contact with raw chicken.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Bake the first side"},{"title":"Cook the tomato BBQ sauce","content":"Put 160 g ketchup, 25 g brown sugar, 25 g cider vinegar, 10 g Worcestershire sauce, 8 g finely chopped garlic, 2 g sweet smoked paprika and 40 g water in a clean saucepan. Stir, heat to small bubbles and simmer gently for about 8 minutes, stirring to dissolve sugar and prevent sticking. It should coat a spoon without becoming caramel. This cooking happens during baking and is not added to the total again. Set about half aside in a clean serving container and use the other half for brushing; never return the brush to the serving sauce.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Cook the tomato BBQ sauce"},{"title":"Turn and check the centre","content":"After the first 20 minutes, turn the wings with tongs and bake for another 15 minutes at 220 °C. Check several large pieces with a clean probe in the thickest meat, touching neither bone nor rack: they must reach at least 74 °C. If they have not, extend baking and check again before glazing. Piece size and oven change the actual timing; browned skin does not establish safety.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Turn and check the centre"},{"title":"Glaze at the end and rest","content":"Once the wings have been checked at 74 °C, brush on a thin coat from the half of the sauce reserved for glazing. Return to the oven at 220 °C for about 5 minutes, watching that the sugar does not blacken; do not use the grill function as a substitute for cooking. Recheck at least 74 °C in thick pieces, remove with oven gloves and rest for 5 minutes. The proposal allows 40 oven minutes plus this rest, but any extra cooking extends the total. Keep the clean serving sauce separate.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Glaze at the end and rest"},{"title":"Serve in four portions","content":"Divide the hot wings into 4 equal portions, sharing out large and small pieces, and serve with the clean reserved sauce. The proposal adds 20 minutes preparation, 40 oven minutes and 5 minutes resting: 65 minutes total, with preheating and sauce overlapping. It has not been kitchen-tested and final weight has not been measured. Nutrition assumes 700 g edible meat and skin for the 1000 g bone-in wings, an unconfirmed 70 % hypothesis, and includes all sauce and oil; that does not mean each serving weighs this amount.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Oven BBQ chicken wings with tomato sauce: Serve in four portions"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Raw chicken wing sections with skin and bone, tips removed","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"Olive oil","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"Fine salt","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Ground black pepper","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"Tomato ketchup","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"Brown sugar","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"Cider vinegar","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"Worcestershire sauce","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"Peeled, very finely chopped garlic","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"Sweet smoked paprika","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"Drinking water","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"One quarter of the wings and all proposed sauce; 4 servings with no measured final weight","method":"Weight eleven edible quantities by their eight USDA values per 100 g, sum and divide by 4. For 1000 g bone-in wings use 700 g edible raw meat and skin: an unmeasured 70 % hypothesis not attributed to USDA. Includes all oil and sauce without deducting drained fat or leftovers.","note":"Ingredient estimate, not laboratory analysis or kitchen testing. The chicken record covers raw meat and skin without bone; the edible assumption is unconfirmed and varies by piece. Generic ketchup and Worcestershire, with smoked paprika approximated by generic paprika. Brands can differ. Cooked weight and consumed sauce were not measured. All eight nutrients exist in the records; missing values are not filled with zero."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Baked chicken wings with red tomato BBQ glaze beside a small bowl of sauce"}],"published":true,"editorial_status":"published","keywords":["BBQ chicken wings","oven chicken wings","tomato barbecue sauce","glazed wings"],"notes":"Editorial proposal, not kitchen-tested. Skin-on bone-in wing sections without tips, already thawed; thawing time is not included. Thaw in the refrigerator, keep chicken at 4 °C or below and follow the package. Do not wash raw chicken; keep its juices away from ready-to-eat foods and clean utensils. A probe in thick meat without touching bone must show at least 74 °C; colour is insufficient. This tomato, vinegar and brown-sugar BBQ sauce differs from honey-soy glaze; no honey or soy sauce is directly added. Worcestershire may contain fish, gluten, soy or other allergens depending on brand: check all labels. Smokiness comes from paprika; actual barbecue cooking is not claimed. Apply sugar at the end and do not crowd pieces. Bone content varies: nutrition assumes 700 g edible raw meat and skin from 1000 g bone-in wings, 70 %, pending a weighed test. This fraction is not a USDA yield or a measured result. All oil and sauce are counted without deducting drained fat or uneaten leftovers; figures may overestimate actual consumption. Smoked paprika is modeled using generic paprika and sauces vary by brand. Less sugar or a different sauce changes flavour, adhesion and nutrition. Other proteins need their own cooking and calculations. Refrigerate leftovers promptly in shallow containers at 4 °C or below and eat within 3–4 days under official cooked-poultry guidance. Do not leave out over 2 hours, or 1 hour above 32 °C. Reheat to 74 °C. Freezing covered portions for up to 2 months is proposed as a domestic quality window, without testing this formula's texture.","seo":{"title":"Oven BBQ chicken wings with tomato sauce, step by step","description":"Tomato BBQ chicken wings for four proposed servings. Late glazing, complete timings, a 74 °C check and estimated nutrition with an explicit edible-weight assumption.","image_alt":"Baked chicken wings with red tomato BBQ glaze beside a small bowl of sauce","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"Are these wings cooked on a barbecue?","a":"This proposal uses an oven at 220 °C. BBQ describes the tomato, vinegar, brown-sugar and smoked-paprika sauce. Smoking or cooking over coals is not claimed."},{"q":"When do I add sauce and how do I know the chicken is ready?","a":"First check at least 74 °C inside several large pieces without touching bone. Brush on the sweet sauce at the end and bake about 5 minutes, watching for burning. Proposed timing does not replace a thermometer."},{"q":"What does nutrition include and how do I keep leftovers?","a":"All sauce and oil are included, assuming 700 g edible weight from 1000 g bone-in wings: an unmeasured, unconfirmed 70 % fraction. Refrigerate promptly at 4 °C or below, eat within 3–4 days and reheat to 74 °C. Do not leave out over 2 hours, or 1 hour above 32 °C."}]},"content_html":"<p>Oven chicken wings with a late-applied BBQ glaze of tomato, brown sugar, vinegar and smoked paprika. Four servings and 65 minutes are proposed, with a 74 °C temperature check in the chicken. Formula, yield and timings await kitchen testing.</p><p>Editorial proposal, not kitchen-tested. Skin-on bone-in wing sections without tips, already thawed; thawing time is not included. Thaw in the refrigerator, keep chicken at 4 °C or below and follow the package. Do not wash raw chicken; keep its juices away from ready-to-eat foods and clean utensils. A probe in thick meat without touching bone must show at least 74 °C; colour is insufficient. This tomato, vinegar and brown-sugar BBQ sauce differs from honey-soy glaze; no honey or soy sauce is directly added. Worcestershire may contain fish, gluten, soy or other allergens depending on brand: check all labels. Smokiness comes from paprika; actual barbecue cooking is not claimed. Apply sugar at the end and do not crowd pieces. Bone content varies: nutrition assumes 700 g edible raw meat and skin from 1000 g bone-in wings, 70 %, pending a weighed test. This fraction is not a USDA yield or a measured result. All oil and sauce are counted without deducting drained fat or uneaten leftovers; figures may overestimate actual consumption. Smoked paprika is modeled using generic paprika and sauces vary by brand. Less sugar or a different sauce changes flavour, adhesion and nutrition. Other proteins need their own cooking and calculations. Refrigerate leftovers promptly in shallow containers at 4 °C or below and eat within 3–4 days under official cooked-poultry guidance. Do not leave out over 2 hours, or 1 hour above 32 °C. Reheat to 74 °C. Freezing covered portions for up to 2 months is proposed as a domestic quality window, without testing this formula&#x27;s texture.</p>"},{"id":"b931260b-d38f-5546-8faa-e003a0b6cd0a","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"ailes-de-poulet-barbecue","public_path":"/fr/ailes-de-poulet-barbecue","source_url":"https://manualdecocina.com/fr/ailes-de-poulet-barbecue/","language":"fr","title":"Ailes de poulet BBQ au four, sauce tomate","excerpt":"Ailes au four glacées en fin de cuisson avec une sauce BBQ tomate. Quatre portions proposées, contrôle de température et nutrition estimée hors poids des os.","summary":"Ailes au four avec un glaçage BBQ de tomate, sucre brun, vinaigre et paprika fumé appliqué à la fin. Quatre portions et 65 minutes sont proposées, avec contrôle de 74 °C dans le poulet. Formule, rendement et durées restent à tester en cuisine.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Facile","course":"Plat principal","cuisine":"Inspiration américaine","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"Ailes de poulet crues avec peau et os, séparées, sans pointes","amount":"1000","unit":"g","group":"Ailes de poulet"},{"name":"Huile d'olive","amount":"10","unit":"g","group":"Ailes de poulet"},{"name":"Sel fin","amount":"3","unit":"g","group":"Ailes de poulet"},{"name":"Poivre noir moulu","amount":"1","unit":"g","group":"Ailes de poulet"},{"name":"Ketchup de tomate","amount":"160","unit":"g","group":"Sauce BBQ"},{"name":"Sucre brun","amount":"25","unit":"g","group":"Sauce BBQ"},{"name":"Vinaigre de cidre","amount":"25","unit":"g","group":"Sauce BBQ"},{"name":"Sauce Worcestershire","amount":"10","unit":"g","group":"Sauce BBQ"},{"name":"Ail épluché très finement haché","amount":"8","unit":"g","group":"Sauce BBQ"},{"name":"Paprika doux fumé","amount":"2","unit":"g","group":"Sauce BBQ"},{"name":"Eau potable","amount":"40","unit":"g","group":"Sauce BBQ"}],"steps":[{"title":"Préchauffer et préparer les ailes","content":"Préchauffez le four à 220 °C, chaleur traditionnelle haut et bas, environ 15 minutes pendant la préparation. Le préchauffage se déroule dans les 20 minutes de préparation proposées. Utilisez 1000 g d'ailes crues séparées avec peau et os, sans pointes, préalablement décongelées au réfrigérateur si nécessaire. Ne lavez pas le poulet. Séchez sans éclabousser avec du papier jetable, jetez-le et lavez mains et surfaces. Posez une grille allant au four dans une plaque métallique profonde d'environ 40 × 30 cm, avec de l'aluminium dessous pour recueillir les jus. Séparez le poulet de la sauce et des ustensiles propres.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Préchauffer et préparer les ailes"},{"title":"Assaisonner et espacer","content":"Mélangez les ailes avec 10 g d'huile d'olive, 3 g de sel et 1 g de poivre noir dans un saladier réservé au poulet cru. Répartissez en une couche sur la grille, avec un peu d'espace entre les morceaux. N'ajoutez pas encore la sauce sucrée. Si les ailes ne tiennent pas sans se chevaucher, utilisez une autre plaque et notez l'effet sur la durée ; évitez la proximité de la résistance supérieure. Nettoyez saladier et ustensiles du cru avant de servir avec.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Assaisonner et espacer"},{"title":"Cuire la première face","content":"Placez la plaque au milieu du four et cuisez environ 20 minutes à 220 °C. La peau commence à dorer et les jus tombent dans la plaque, mais les ailes ne sont pas encore considérées prêtes à manger. Ne jugez pas uniquement à la couleur. Préparez alors la sauce dans une casserole séparée, sans contact avec le poulet cru.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Cuire la première face"},{"title":"Cuire la sauce BBQ tomate","content":"Mettez dans une casserole propre 160 g de ketchup, 25 g de sucre brun, 25 g de vinaigre de cidre, 10 g de sauce Worcestershire, 8 g d'ail très finement haché, 2 g de paprika doux fumé et 40 g d'eau. Mélangez, chauffez jusqu'à de petites bulles et cuisez doucement environ 8 minutes en remuant pour dissoudre le sucre et éviter qu'il attache. La sauce doit napper la cuillère sans devenir du caramel. Elle cuit pendant le passage au four et n'est pas ajoutée une seconde fois au total. Réservez environ la moitié dans un récipient propre pour servir, l'autre pour badigeonner. Ne replongez pas le pinceau dans la sauce de service.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Cuire la sauce BBQ tomate"},{"title":"Retourner et contrôler le cœur","content":"Après les premières 20 minutes, retournez les ailes avec une pince et cuisez encore 15 minutes à 220 °C. Mesurez plusieurs gros morceaux avec une sonde propre dans la chair la plus épaisse, sans toucher os ni grille : au moins 74 °C sont nécessaires. Sinon, prolongez et contrôlez à nouveau avant de glacer. La taille et le four changent la durée réelle ; une peau dorée ne garantit pas la sécurité.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Retourner et contrôler le cœur"},{"title":"Glacer à la fin et laisser reposer","content":"Après avoir vérifié 74 °C, badigeonnez une fine couche de la moitié de sauce prévue pour le glaçage. Remettez au four à 220 °C environ 5 minutes, en surveillant que le sucre ne noircisse pas ; le gril ne remplace pas la cuisson. Vérifiez à nouveau au moins 74 °C dans les morceaux épais, sortez avec des gants et laissez reposer 5 minutes. On propose 40 minutes de four plus ce repos ; toute cuisson supplémentaire allonge le total. Gardez la sauce de service séparée et propre.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Glacer à la fin et laisser reposer"},{"title":"Servir en quatre portions","content":"Répartissez les ailes chaudes en 4 portions égales, avec gros et petits morceaux, et servez la sauce propre réservée. La proposition compte 20 minutes de préparation, 40 de four et 5 de repos : 65 minutes au total, préchauffage et sauce étant simultanés. Aucun essai culinaire ni pesée finale n'a été réalisé. La nutrition suppose 700 g de chair et peau comestibles pour 1000 g avec os, hypothèse de 70 % à confirmer, et comprend toute la sauce et l'huile ; ce n'est pas le poids de chaque portion.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Ailes de poulet BBQ au four, sauce tomate: Servir en quatre portions"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Ailes de poulet crues avec peau et os, séparées, sans pointes","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"Huile d'olive","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"Sel fin","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Poivre noir moulu","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"Ketchup de tomate","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"Sucre brun","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"Vinaigre de cidre","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"Sauce Worcestershire","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"Ail épluché très finement haché","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"Paprika doux fumé","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"Eau potable","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"Un quart des ailes et de toute la sauce proposée ; 4 portions sans poids final mesuré","method":"Pondérer onze quantités comestibles par leurs huit valeurs USDA pour 100 g, additionner et diviser par 4. Pour 1000 g avec os, utiliser 700 g de chair et peau crues comestibles, hypothèse de 70 % non mesurée et non attribuée à USDA. Toute l'huile et la sauce sont comptées sans retirer graisse égouttée ni restes.","note":"Estimation d'ingrédients, ni analyse ni essai culinaire. La fiche de poulet couvre chair et peau crues sans os ; la fraction supposée reste à confirmer et varie selon les morceaux. Ketchup et Worcestershire génériques, paprika fumé approché par paprika générique. Marques variables. Poids cuit et sauce mangée non mesurés. Les huit nutriments sont présents ; aucune absence n'est remplacée par zéro."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Ailes de poulet cuites au four, glaçage rouge BBQ tomate et petit bol de sauce"}],"published":true,"editorial_status":"published","keywords":["ailes de poulet BBQ","ailes au four","sauce barbecue tomate","ailes glacées"],"notes":"Proposition éditoriale sans essai culinaire. Ailes avec peau et os sans pointes, déjà décongelées ; décongélation hors durées. Décongelez au réfrigérateur, gardez le poulet à 4 °C maximum et suivez l'emballage. Ne lavez pas le poulet cru et séparez ses jus des aliments et ustensiles propres. La sonde dans la chair épaisse, sans toucher l'os, doit indiquer au moins 74 °C ; la couleur ne suffit pas. Cette BBQ tomate-vinaigre-sucre brun diffère d'un glaçage miel-soja ; ni miel ni sauce soja ne sont directement ajoutés. Worcestershire peut contenir poisson, gluten, soja ou d'autres allergènes : vérifiez les étiquettes. La note fumée vient du paprika, pas d'une cuisson sur barbecue revendiquée. Appliquez le sucre à la fin et n'entassez pas les morceaux. La nutrition suppose 700 g de chair et peau crues comestibles sur 1000 g avec os, soit 70 %, à confirmer par pesée. Ce n'est ni un rendement USDA ni un résultat mesuré. Toute l'huile et toute la sauce sont comptées, sans retrait de graisse égouttée ou restes non mangés ; les valeurs peuvent surestimer la consommation. Paprika fumé modélisé avec paprika générique, sauces variables selon la marque. Moins de sucre ou autre sauce modifie goût, adhérence et nutrition. Pour une autre protéine, adaptez cuisson et calcul. Réfrigérez rapidement les restes en récipients peu profonds à 4 °C maximum, puis consommez en 3–4 jours selon la recommandation officielle pour poulet cuit. Ne dépassez pas 2 heures dehors, ou 1 heure au-dessus de 32 °C. Réchauffez à 74 °C. Congeler des portions couvertes jusqu'à 2 mois est proposé comme délai domestique de qualité, sans essai de texture.","seo":{"title":"Ailes de poulet BBQ au four et sauce tomate, pas à pas","description":"Ailes BBQ tomate pour quatre portions proposées. Glaçage final, durées complètes, contrôle de 74 °C et nutrition estimée avec hypothèse de poids comestible.","image_alt":"Ailes de poulet cuites au four, glaçage rouge BBQ tomate et petit bol de sauce","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"Les ailes cuisent-elles sur un barbecue ?","a":"Cette proposition utilise un four à 220 °C. BBQ décrit la sauce tomate, vinaigre, sucre brun et paprika fumé. Fumage et cuisson sur braises ne sont pas revendiqués."},{"q":"Quand ajouter la sauce et vérifier la cuisson ?","a":"Vérifiez d'abord au moins 74 °C dans plusieurs gros morceaux sans toucher l'os. Badigeonnez la sauce sucrée à la fin et cuisez environ 5 minutes sans brûler. La durée proposée ne remplace pas le thermomètre."},{"q":"Que comprend la nutrition et comment garder les restes ?","a":"Toute la sauce et l'huile sont comptées, avec 700 g comestibles supposés pour 1000 g avec os, fraction de 70 % non mesurée à confirmer. Réfrigérez à 4 °C maximum, consommez en 3–4 jours et réchauffez à 74 °C. Ne dépassez pas 2 heures dehors, ou 1 heure au-dessus de 32 °C."}]},"content_html":"<p>Ailes au four avec un glaçage BBQ de tomate, sucre brun, vinaigre et paprika fumé appliqué à la fin. Quatre portions et 65 minutes sont proposées, avec contrôle de 74 °C dans le poulet. Formule, rendement et durées restent à tester en cuisine.</p><p>Proposition éditoriale sans essai culinaire. Ailes avec peau et os sans pointes, déjà décongelées ; décongélation hors durées. Décongelez au réfrigérateur, gardez le poulet à 4 °C maximum et suivez l&#x27;emballage. Ne lavez pas le poulet cru et séparez ses jus des aliments et ustensiles propres. La sonde dans la chair épaisse, sans toucher l&#x27;os, doit indiquer au moins 74 °C ; la couleur ne suffit pas. Cette BBQ tomate-vinaigre-sucre brun diffère d&#x27;un glaçage miel-soja ; ni miel ni sauce soja ne sont directement ajoutés. Worcestershire peut contenir poisson, gluten, soja ou d&#x27;autres allergènes : vérifiez les étiquettes. La note fumée vient du paprika, pas d&#x27;une cuisson sur barbecue revendiquée. Appliquez le sucre à la fin et n&#x27;entassez pas les morceaux. La nutrition suppose 700 g de chair et peau crues comestibles sur 1000 g avec os, soit 70 %, à confirmer par pesée. Ce n&#x27;est ni un rendement USDA ni un résultat mesuré. Toute l&#x27;huile et toute la sauce sont comptées, sans retrait de graisse égouttée ou restes non mangés ; les valeurs peuvent surestimer la consommation. Paprika fumé modélisé avec paprika générique, sauces variables selon la marque. Moins de sucre ou autre sauce modifie goût, adhérence et nutrition. Pour une autre protéine, adaptez cuisson et calcul. Réfrigérez rapidement les restes en récipients peu profonds à 4 °C maximum, puis consommez en 3–4 jours selon la recommandation officielle pour poulet cuit. Ne dépassez pas 2 heures dehors, ou 1 heure au-dessus de 32 °C. Réchauffez à 74 °C. Congeler des portions couvertes jusqu&#x27;à 2 mois est proposé comme délai domestique de qualité, sans essai de texture.</p>"},{"id":"f50af27e-ecc8-5e7b-b10a-3bbaa9f8d4e8","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"ali-di-pollo-al-barbecue","public_path":"/it/ali-di-pollo-al-barbecue","source_url":"https://manualdecocina.com/it/ali-di-pollo-al-barbecue/","language":"it","title":"Ali di pollo BBQ al forno con salsa di pomodoro","excerpt":"Ali al forno glassate alla fine con salsa BBQ al pomodoro. Quattro porzioni proposte, controllo della temperatura e nutrizione stimata escludendo le ossa.","summary":"Ali al forno con glassa BBQ di pomodoro, zucchero di canna, aceto e paprika affumicata applicata alla fine. Si propongono quattro porzioni e 65 minuti, con controllo di 74 °C nel pollo. Formula, resa e tempi attendono una prova in cucina.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Facile","course":"Secondo piatto","cuisine":"Ispirazione statunitense","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"Ali di pollo crude con pelle e ossa, divise, senza punte","amount":"1000","unit":"g","group":"Ali di pollo"},{"name":"Olio d'oliva","amount":"10","unit":"g","group":"Ali di pollo"},{"name":"Sale fino","amount":"3","unit":"g","group":"Ali di pollo"},{"name":"Pepe nero macinato","amount":"1","unit":"g","group":"Ali di pollo"},{"name":"Ketchup di pomodoro","amount":"160","unit":"g","group":"Salsa BBQ"},{"name":"Zucchero di canna","amount":"25","unit":"g","group":"Salsa BBQ"},{"name":"Aceto di mele","amount":"25","unit":"g","group":"Salsa BBQ"},{"name":"Salsa Worcestershire","amount":"10","unit":"g","group":"Salsa BBQ"},{"name":"Aglio sbucciato tritato molto finemente","amount":"8","unit":"g","group":"Salsa BBQ"},{"name":"Paprika dolce affumicata","amount":"2","unit":"g","group":"Salsa BBQ"},{"name":"Acqua potabile","amount":"40","unit":"g","group":"Salsa BBQ"}],"steps":[{"title":"Preriscaldare e preparare le ali","content":"Preriscalda il forno a 220 °C, statico sopra e sotto, per circa 15 minuti mentre prepari gli ingredienti; il preriscaldamento si sovrappone ai 20 minuti di preparazione proposti. Usa 1000 g di ali crude divise con pelle e ossa, senza punte, già scongelate in frigorifero se necessario. Non lavare il pollo. Asciuga senza schizzi con carta monouso, gettala e lava mani e superfici. Sistema una griglia da forno in una teglia metallica profonda di circa 40 × 30 cm, con alluminio sotto per raccogliere i succhi. Tieni il pollo separato da salsa e utensili puliti.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Preriscaldare e preparare le ali"},{"title":"Condire e distribuire senza ammucchiare","content":"Mescola le ali con 10 g di olio d'oliva, 3 g di sale e 1 g di pepe nero in una ciotola riservata al pollo crudo. Distribuiscile in un solo strato sulla griglia, lasciando spazio tra i pezzi. Non aggiungere ancora la salsa dolce. Se non entrano senza sovrapporsi, usa un'altra teglia e annota l'effetto sul tempo; non avvicinarle alla resistenza superiore. Pulisci ciotola e utensili del crudo prima di servirvi il cibo.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Condire e distribuire senza ammucchiare"},{"title":"Cuocere il primo lato","content":"Metti la teglia nella zona centrale del forno e cuoci le ali per circa 20 minuti a 220 °C. La pelle comincia a dorare e i succhi cadono nella teglia, ma le ali non sono ancora considerate pronte da mangiare. Non basarti solo sul colore. Intanto prepara la salsa in un pentolino separato senza contatto con il pollo crudo.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Cuocere il primo lato"},{"title":"Cuocere la salsa BBQ al pomodoro","content":"Metti in un pentolino pulito 160 g di ketchup, 25 g di zucchero di canna, 25 g di aceto di mele, 10 g di salsa Worcestershire, 8 g di aglio molto tritato, 2 g di paprika dolce affumicata e 40 g di acqua. Mescola, scalda fino a piccole bolle e cuoci dolcemente circa 8 minuti, sciogliendo lo zucchero ed evitando che attacchi. Deve velare il cucchiaio senza diventare caramello. Questa cottura avviene durante il forno e non si aggiunge nuovamente al totale. Conserva circa metà in un recipiente pulito per servire e usa l'altra metà per spennellare; non rimettere il pennello nella salsa da servire.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Cuocere la salsa BBQ al pomodoro"},{"title":"Girare e verificare l'interno","content":"Dopo i primi 20 minuti gira le ali con pinze e cuoci altri 15 minuti a 220 °C. Misura vari pezzi grandi con una sonda pulita nella carne più spessa, senza toccare ossa o griglia: devono raggiungere almeno 74 °C. Altrimenti prolunga la cottura e ricontrolla prima della glassa. Dimensione e forno cambiano il tempo reale; la pelle dorata non garantisce sicurezza.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Girare e verificare l'interno"},{"title":"Glassare alla fine e riposare","content":"Dopo aver verificato 74 °C, spennella un velo della metà di salsa destinata alla glassa. Rimetti in forno a 220 °C per circa 5 minuti, controllando che lo zucchero non annerisca; il grill non sostituisce la cottura. Ricontrolla almeno 74 °C nei pezzi spessi, estrai con guanti e lascia riposare 5 minuti. Si propongono 40 minuti di forno più questo riposo; altra cottura prolunga il totale. Tieni separata e pulita la salsa da servire.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Glassare alla fine e riposare"},{"title":"Servire in quattro porzioni","content":"Dividi le ali calde in 4 porzioni uguali, distribuendo pezzi grandi e piccoli, e accompagna con la salsa pulita riservata. La proposta somma 20 minuti di preparazione, 40 di forno e 5 di riposo: 65 minuti totali, con preriscaldamento e salsa sovrapposti. Non è stata provata in cucina né pesata a fine cottura. La nutrizione presume 700 g commestibili di carne e pelle dai 1000 g con ossa, un'ipotesi del 70 % da confermare, e include tutta la salsa e l'olio; non è il peso di ogni porzione.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Ali di pollo BBQ al forno con salsa di pomodoro: Servire in quattro porzioni"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Ali di pollo crude con pelle e ossa, divise, senza punte","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"Olio d'oliva","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"Sale fino","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Pepe nero macinato","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"Ketchup di pomodoro","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"Zucchero di canna","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"Aceto di mele","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"Salsa Worcestershire","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"Aglio sbucciato tritato molto finemente","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"Paprika dolce affumicata","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"Acqua potabile","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"Un quarto delle ali e di tutta la salsa proposta; 4 porzioni senza peso finale misurato","method":"Pondera undici quantità commestibili con gli otto valori USDA per 100 g, somma e dividi per 4. Per 1000 g con ossa usa 700 g di carne e pelle crude commestibili, ipotesi del 70 % non misurata né attribuita a USDA. Include tutto l'olio e la salsa senza sottrarre grasso o avanzi.","note":"Stima degli ingredienti, non analisi né prova in cucina. Dati del pollo per carne e pelle crude senza ossa; quota commestibile da confermare e variabile per pezzo. Ketchup e Worcestershire generici, paprika affumicata approssimata con paprika generica. Marche diverse, peso cotto e salsa mangiata non misurati. Tutti gli otto nutrienti sono presenti; dati mancanti non sostituiti con zero."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Ali di pollo al forno con glassa rossa BBQ al pomodoro accanto a una ciotolina di salsa"}],"published":true,"editorial_status":"published","keywords":["ali di pollo BBQ","ali al forno","salsa barbecue al pomodoro","ali glassate"],"notes":"Proposta editoriale senza prova in cucina. Ali con ossa e pelle senza punte, già scongelate; scongelamento escluso dai tempi. Scongela in frigorifero, tieni il pollo a 4 °C o meno e segui la confezione. Non lavare il pollo crudo e separa i succhi da alimenti e utensili puliti. Sonda nella carne spessa senza toccare ossa: almeno 74 °C, il colore non basta. Questa BBQ di pomodoro, aceto e zucchero di canna è diversa da glassa miele-soia; non si aggiungono direttamente miele o salsa di soia. Worcestershire può contenere pesce, glutine, soia o altri allergeni secondo la marca: controlla le etichette. L'affumicato viene dalla paprika, non da una cottura sul barbecue dichiarata. Zucchero alla fine e pezzi non ammucchiati. Il calcolo assume 700 g di carne e pelle crude commestibili da 1000 g con ossa, 70 %, da confermare con pesata. Non è una resa USDA né misurata. Include tutto l'olio e la salsa senza sottrarre grasso colato o avanzi non mangiati; può sovrastimare il consumo reale. Paprika affumicata modellata con paprika generica, salse variabili per marca. Meno zucchero o altra salsa cambia gusto, adesione e nutrizione. Altre proteine richiedono cotture e calcoli propri. Refrigera prontamente gli avanzi in contenitori poco profondi a 4 °C o meno e consuma entro 3–4 giorni secondo la guida ufficiale per pollo cotto. Non lasciare fuori oltre 2 ore, o 1 ora sopra 32 °C. Riscalda a 74 °C. Fino a 2 mesi congelati è una proposta domestica di qualità, senza prova della consistenza.","seo":{"title":"Ali di pollo BBQ al forno con pomodoro passo passo","description":"Ali BBQ al pomodoro per quattro porzioni proposte. Glassa finale, tempi completi, verifica di 74 °C e nutrizione stimata con quota commestibile dichiarata.","image_alt":"Ali di pollo al forno con glassa rossa BBQ al pomodoro accanto a una ciotolina di salsa","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"Le ali si cuociono sul barbecue?","a":"Questa proposta usa il forno a 220 °C. BBQ descrive la salsa di pomodoro, aceto, zucchero di canna e paprika affumicata. Non si dichiara affumicatura né cottura sulla brace."},{"q":"Quando aggiungo la salsa e verifico il pollo?","a":"Prima controlla almeno 74 °C dentro diversi pezzi grandi senza toccare ossa. Spennella la salsa dolce alla fine e cuoci circa 5 minuti senza bruciare. Il tempo proposto non sostituisce il termometro."},{"q":"Cosa comprende la nutrizione e come conservo gli avanzi?","a":"Tutta la salsa e l'olio, assumendo 700 g commestibili da 1000 g con ossa: quota del 70 % non misurata da confermare. Refrigera a 4 °C o meno, consuma in 3–4 giorni e riscalda a 74 °C. Non lasciare fuori oltre 2 ore, o 1 ora sopra 32 °C."}]},"content_html":"<p>Ali al forno con glassa BBQ di pomodoro, zucchero di canna, aceto e paprika affumicata applicata alla fine. Si propongono quattro porzioni e 65 minuti, con controllo di 74 °C nel pollo. Formula, resa e tempi attendono una prova in cucina.</p><p>Proposta editoriale senza prova in cucina. Ali con ossa e pelle senza punte, già scongelate; scongelamento escluso dai tempi. Scongela in frigorifero, tieni il pollo a 4 °C o meno e segui la confezione. Non lavare il pollo crudo e separa i succhi da alimenti e utensili puliti. Sonda nella carne spessa senza toccare ossa: almeno 74 °C, il colore non basta. Questa BBQ di pomodoro, aceto e zucchero di canna è diversa da glassa miele-soia; non si aggiungono direttamente miele o salsa di soia. Worcestershire può contenere pesce, glutine, soia o altri allergeni secondo la marca: controlla le etichette. L&#x27;affumicato viene dalla paprika, non da una cottura sul barbecue dichiarata. Zucchero alla fine e pezzi non ammucchiati. Il calcolo assume 700 g di carne e pelle crude commestibili da 1000 g con ossa, 70 %, da confermare con pesata. Non è una resa USDA né misurata. Include tutto l&#x27;olio e la salsa senza sottrarre grasso colato o avanzi non mangiati; può sovrastimare il consumo reale. Paprika affumicata modellata con paprika generica, salse variabili per marca. Meno zucchero o altra salsa cambia gusto, adesione e nutrizione. Altre proteine richiedono cotture e calcoli propri. Refrigera prontamente gli avanzi in contenitori poco profondi a 4 °C o meno e consuma entro 3–4 giorni secondo la guida ufficiale per pollo cotto. Non lasciare fuori oltre 2 ore, o 1 ora sopra 32 °C. Riscalda a 74 °C. Fino a 2 mesi congelati è una proposta domestica di qualità, senza prova della consistenza.</p>"},{"id":"b1c351fb-3b6e-5f35-b347-a010db304191","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"バーベキューチキンウイング","public_path":"/ja/バーベキューチキンウイング","source_url":null,"language":"ja","title":"トマトBBQソースのオーブンチキンウイング","excerpt":"焼き終わりにトマトBBQソースを塗る手羽の提案レシピ。四人分、中心温度の確認と、骨を除いて計算した推定栄養値を掲載。","summary":"トマト、ブラウンシュガー、酢、スモークパプリカのBBQソースを最後に塗って焼く手羽です。提案は四人分、65分で、鶏肉の中心74 °Cを確認します。配合、出来上がり、時間は調理試験前の推定です。","category":"主菜","category_slug":"platos-principales","difficulty":"簡単","course":"主菜","cuisine":"米国料理を参考にしたもの","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"生の鶏手羽、皮と骨付き、関節で分けて先端を除いたもの","amount":"1000","unit":"g","group":"手羽"},{"name":"オリーブ油","amount":"10","unit":"g","group":"手羽"},{"name":"細粒塩","amount":"3","unit":"g","group":"手羽"},{"name":"黒こしょう粉","amount":"1","unit":"g","group":"手羽"},{"name":"トマトケチャップ","amount":"160","unit":"g","group":"BBQソース"},{"name":"ブラウンシュガー","amount":"25","unit":"g","group":"BBQソース"},{"name":"りんご酢","amount":"25","unit":"g","group":"BBQソース"},{"name":"ウスターシャーソース","amount":"10","unit":"g","group":"BBQソース"},{"name":"皮をむき、ごく細かく刻んだにんにく","amount":"8","unit":"g","group":"BBQソース"},{"name":"辛くないスモークパプリカパウダー","amount":"2","unit":"g","group":"BBQソース"},{"name":"飲用水","amount":"40","unit":"g","group":"BBQソース"}],"steps":[{"title":"予熱して手羽を準備する","content":"オーブンを上下加熱の220 °Cで約15分予熱し、その間に材料を準備します。予熱は提案の準備20分に重ねます。先端を除き、関節で分けた皮と骨付きの生手羽1000 gを使い、必要なら事前に冷蔵庫で解凍します。鶏肉を洗わないでください。飛び散らないよう使い捨てペーパーで水分を押さえ、捨ててから手と作業面を洗浄します。約40 × 30 cmの深い金属天板にオーブン対応の網を載せ、下にアルミホイルを敷いて肉汁を受けます。鶏肉はソースや清潔な器具と分けます。","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 予熱して手羽を準備する"},{"title":"味付けし、重ねず並べる","content":"生鶏肉専用のボウルで手羽をオリーブ油10 g、塩3 g、黒こしょう1 gと混ぜます。網に重ならないよう少し間隔を空けて並べます。甘いソースはまだ加えません。詰めずに入らなければ天板を増やし、時間への影響を記録します。上のヒーターに近づけないでください。生肉用ボウルと器具は、盛り付けに使う前に洗浄します。","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 味付けし、重ねず並べる"},{"title":"最初の面を焼く","content":"天板をオーブンの中央に入れ、220 °Cで約20分焼きます。皮に焼き色がつき始め、肉汁が天板に落ちますが、まだ食べられるとは判断しません。色だけで決めないでください。この間に、生鶏肉に触れない別鍋でソースを作ります。","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 最初の面を焼く"},{"title":"トマトBBQソースを煮る","content":"清潔な小鍋にケチャップ160 g、ブラウンシュガー25 g、りんご酢25 g、ウスターシャーソース10 g、刻んだにんにく8 g、辛くないスモークパプリカ2 g、水40 gを入れます。混ぜて小さな泡が出るまで温め、約8分穏やかに煮ます。砂糖を溶かし、こびりつかないよう混ぜます。スプーンを覆う濃度にし、カラメル状にはしません。これはオーブン加熱中の作業で、総時間に再加算しません。半量ほどを清潔な容器に取り分けて食卓用とし、残りを塗るために使います。刷毛を食卓用ソースに戻さないでください。","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: トマトBBQソースを煮る"},{"title":"返して中心を確認する","content":"最初の20分が終わったらトングで返し、220 °Cでさらに15分焼きます。大きな手羽をいくつか、肉の最も厚い部分に清潔な温度計を差して測り、骨や網には触れさせません。少なくとも74 °Cに達する必要があります。足りなければ焼き続け、ソースを塗る前に再確認します。大きさやオーブンで実際の時間は変わり、皮の焼き色だけでは安全を証明できません。","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 返して中心を確認する"},{"title":"最後にソースを塗って休ませる","content":"手羽が74 °Cに達したことを確認してから、塗るための半量のソースを薄く塗ります。220 °Cのオーブンに約5分戻し、砂糖が黒く焦げないよう見ます。グリル機能を加熱の代わりにしないでください。厚い部分で再び少なくとも74 °Cを確認し、ミトンで取り出して5分休ませます。提案はオーブン40分とこの休ませ時間ですが、追加加熱があれば総時間は延びます。取り分けた食卓用ソースは清潔に別置きします。","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 最後にソースを塗って休ませる"},{"title":"四人分に分けて盛り付ける","content":"温かい手羽を4等分し、大きいものと小さいものを分けて、清潔な取り分けソースを添えます。提案は準備20分、オーブン40分、休ませ5分で、合計65分です。予熱とソース調理は重ねます。調理試験や出来上がり重量の測定はしていません。栄養は骨付き1000 gから可食の肉と皮700 gという未確認の70 %仮定を使い、ソースと油を全量含みます。これが一人分の重量という意味ではありません。","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"トマトBBQソースのオーブンチキンウイング: 四人分に分けて盛り付ける"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"生の鶏手羽、皮と骨付き、関節で分けて先端を除いたもの","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"オリーブ油","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"細粒塩","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"黒こしょう粉","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"トマトケチャップ","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"ブラウンシュガー","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"りんご酢","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"ウスターシャーソース","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"皮をむき、ごく細かく刻んだにんにく","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"辛くないスモークパプリカパウダー","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"飲用水","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"手羽と提案ソース全量の四分の一。4人分で、出来上がり重量は未測定","method":"十一種類の可食量をUSDAの100 g当たり八項目で加重し、合計を4で割ります。骨付き手羽1000 gには生の肉と皮700 g、70 %という未測定仮定を使い、USDAの歩留まりとしません。油とソース全量を含み、落ちた脂や残りは差し引きません。","note":"材料の推定であり、分析や調理試験ではありません。鶏肉データは骨なしの生の肉と皮で、可食割合は未確認で個体差があります。一般ケチャップとウスターシャー、一般パプリカによるスモーク品の近似です。製品は異なり得ます。加熱後重量と食べたソース量は未測定です。八項目がすべてデータに存在し、欠損をゼロにしていません。"},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"赤いトマトBBQソースを塗って焼いた鶏手羽と、小さなソースのボウル"}],"published":true,"editorial_status":"published","keywords":["BBQチキンウイング","手羽のオーブン焼き","トマトBBQソース","手羽のグレーズ"],"notes":"調理試験をしていない編集上の提案です。先端を除いた皮と骨付き手羽を、解凍済みで使います。解凍時間は含みません。冷蔵庫で解凍し、4 °C以下で保ち、包装表示に従います。生鶏肉を洗わず、肉汁を清潔な器具やそのまま食べる食品から離します。肉の厚い部分を骨に触れない温度計で測り、74 °C以上を確認します。色だけでは足りません。トマト、酢、ブラウンシュガーのBBQソースで、はちみつとしょうゆの味付けとは別です。はちみつやしょうゆは直接加えません。ウスターシャーソースには魚、小麦、大豆などが含まれる場合があるため、全製品の表示を確認します。燻製の風味はパプリカによるもので、実際に炭火や燻製で調理したとは述べません。砂糖は最後に塗り、手羽を詰めて並べません。骨の割合は変動し、栄養計算は骨付き1000 gから生の可食肉と皮700 g、70 %を仮定しています。計量での確認前であり、USDAの歩留まりでも実測値でもありません。油とソース全量を計上し、落ちた脂や食べ残しは差し引かず、実際の摂取を多めに見積もる可能性があります。スモークパプリカは一般パプリカのデータで近似し、ソースも製品で変わります。砂糖を減らしたりソースを変えると味、付着、栄養が変わります。別のたんぱく源には独自の加熱と計算が必要です。残りは浅い容器で速やかに4 °C以下に冷蔵し、公的な加熱済み鶏肉の目安に従い3–4日以内に食べます。室温2時間、32 °Cを超える場合1時間を超えて置かず、再加熱は74 °Cにします。蓋付きで冷凍2か月までという期間は家庭用の品質提案で、この配合の食感は未試験です。","seo":{"title":"トマトBBQソースのオーブン手羽の作り方","description":"四人分を提案するトマトBBQチキンウイング。最後のソース塗り、全工程の時間、74 °C確認、可食割合を明示した推定栄養値を掲載。","image_alt":"赤いトマトBBQソースを塗って焼いた鶏手羽と、小さなソースのボウル","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"バーベキューで焼きますか？","a":"この提案は220 °Cのオーブンを使います。BBQはトマト、酢、ブラウンシュガー、スモークパプリカのソースの名称で、燻製や炭火調理を行ったとは述べません。"},{"q":"いつソースを塗り、加熱を確認しますか？","a":"まず大きな手羽をいくつか、骨に触れずに中心74 °C以上と確認します。甘いソースを最後に塗り、焦げないよう約5分焼きます。提案時間は温度計の代わりになりません。"},{"q":"栄養計算と残りの保存は？","a":"ソースと油の全量を含み、骨付き1000 gから可食700 gという未測定で未確認の70 %割合を仮定します。速やかに4 °C以下に冷蔵し、3–4日以内に食べ、74 °Cまで再加熱します。室温2時間、32 °C超なら1時間を超えて置きません。"}]},"content_html":"<p>トマト、ブラウンシュガー、酢、スモークパプリカのBBQソースを最後に塗って焼く手羽です。提案は四人分、65分で、鶏肉の中心74 °Cを確認します。配合、出来上がり、時間は調理試験前の推定です。</p><p>調理試験をしていない編集上の提案です。先端を除いた皮と骨付き手羽を、解凍済みで使います。解凍時間は含みません。冷蔵庫で解凍し、4 °C以下で保ち、包装表示に従います。生鶏肉を洗わず、肉汁を清潔な器具やそのまま食べる食品から離します。肉の厚い部分を骨に触れない温度計で測り、74 °C以上を確認します。色だけでは足りません。トマト、酢、ブラウンシュガーのBBQソースで、はちみつとしょうゆの味付けとは別です。はちみつやしょうゆは直接加えません。ウスターシャーソースには魚、小麦、大豆などが含まれる場合があるため、全製品の表示を確認します。燻製の風味はパプリカによるもので、実際に炭火や燻製で調理したとは述べません。砂糖は最後に塗り、手羽を詰めて並べません。骨の割合は変動し、栄養計算は骨付き1000 gから生の可食肉と皮700 g、70 %を仮定しています。計量での確認前であり、USDAの歩留まりでも実測値でもありません。油とソース全量を計上し、落ちた脂や食べ残しは差し引かず、実際の摂取を多めに見積もる可能性があります。スモークパプリカは一般パプリカのデータで近似し、ソースも製品で変わります。砂糖を減らしたりソースを変えると味、付着、栄養が変わります。別のたんぱく源には独自の加熱と計算が必要です。残りは浅い容器で速やかに4 °C以下に冷蔵し、公的な加熱済み鶏肉の目安に従い3–4日以内に食べます。室温2時間、32 °Cを超える場合1時間を超えて置かず、再加熱は74 °Cにします。蓋付きで冷凍2か月までという期間は家庭用の品質提案で、この配合の食感は未試験です。</p>"},{"id":"e7b57ca6-9698-5f80-8683-3128eeb3843c","recipe_group_id":"82a37dfd-c53c-4dd9-968b-aa24976da70f","slug":"asinhas-de-frango-barbecue","public_path":"/pt/asinhas-de-frango-barbecue","source_url":null,"language":"pt","title":"Asinhas de frango BBQ no forno com molho de tomate","excerpt":"Asinhas no forno pinceladas no final com molho BBQ de tomate. Quatro porções propostas, temperatura de segurança e nutrição estimada sem contar ossos.","summary":"Asinhas no forno com cobertura BBQ de tomate, açúcar mascavo, vinagre e páprica defumada aplicada no final. Propõem-se quatro porções e 65 minutos, com conferência de 74 °C no frango. Fórmula, rendimento e tempos aguardam teste de cozinha.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Fácil","course":"Prato principal","cuisine":"Inspiração estadunidense","prep_time_minutes":20,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"ingredients":[{"name":"Asinhas de frango cruas com pele e osso, separadas, sem pontas","amount":"1000","unit":"g","group":"Asinhas"},{"name":"Azeite de oliva","amount":"10","unit":"g","group":"Asinhas"},{"name":"Sal fino","amount":"3","unit":"g","group":"Asinhas"},{"name":"Pimenta-do-reino moída","amount":"1","unit":"g","group":"Asinhas"},{"name":"Ketchup de tomate","amount":"160","unit":"g","group":"Molho BBQ"},{"name":"Açúcar mascavo","amount":"25","unit":"g","group":"Molho BBQ"},{"name":"Vinagre de maçã","amount":"25","unit":"g","group":"Molho BBQ"},{"name":"Molho Worcestershire","amount":"10","unit":"g","group":"Molho BBQ"},{"name":"Alho descascado bem picadinho","amount":"8","unit":"g","group":"Molho BBQ"},{"name":"Páprica doce defumada","amount":"2","unit":"g","group":"Molho BBQ"},{"name":"Água potável","amount":"40","unit":"g","group":"Molho BBQ"}],"steps":[{"title":"Preaqueça e prepare as asinhas","content":"Preaqueça o forno a 220 °C, calor superior e inferior, por cerca de 15 minutos enquanto prepara os ingredientes; o preaquecimento se sobrepõe aos 20 minutos de preparo propostos. Use 1000 g de asinhas cruas separadas com pele e osso, sem pontas, já descongeladas na geladeira se necessário. Não lave o frango. Seque com papel descartável sem respingar, jogue fora e lave mãos e superfícies. Coloque uma grade própria para forno dentro de uma assadeira metálica funda de cerca de 40 × 30 cm, com alumínio embaixo para recolher os sucos. Separe o frango do molho e dos utensílios limpos.","image_url":"/recetas/alitas-bbq/paso-01.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Preaqueça e prepare as asinhas"},{"title":"Tempere e distribua sem amontoar","content":"Misture as asinhas com 10 g de azeite, 3 g de sal e 1 g de pimenta-do-reino em uma tigela reservada ao frango cru. Distribua em uma camada na grade, com espaço entre as peças. Não coloque ainda o molho doce. Se não couberem sem amontoar, use outra assadeira e registre o efeito no tempo; evite a resistência superior. Limpe tigela e utensílios do cru antes de usá-los para servir.","image_url":"/recetas/alitas-bbq/paso-02.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Tempere e distribua sem amontoar"},{"title":"Asse a primeira face","content":"Coloque a assadeira no centro do forno e asse por cerca de 20 minutos a 220 °C. A pele começa a dourar e os sucos caem na assadeira, mas as asinhas ainda não são consideradas prontas para comer. Não julgue apenas pela cor. Durante esse período prepare o molho em panela separada, sem contato com frango cru.","image_url":"/recetas/alitas-bbq/paso-03.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Asse a primeira face"},{"title":"Cozinhe o molho BBQ de tomate","content":"Coloque numa panela limpa 160 g de ketchup, 25 g de açúcar mascavo, 25 g de vinagre de maçã, 10 g de molho Worcestershire, 8 g de alho bem picado, 2 g de páprica doce defumada e 40 g de água. Mexa, aqueça até bolhas pequenas e cozinhe suavemente cerca de 8 minutos, dissolvendo o açúcar e evitando que grude. Deve cobrir a colher sem virar caramelo. O molho cozinha durante o forno e não é somado novamente ao total. Reserve aproximadamente metade num recipiente limpo para servir e use a outra metade para pincelar; não devolva o pincel ao molho de servir.","image_url":"/recetas/alitas-bbq/paso-04.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Cozinhe o molho BBQ de tomate"},{"title":"Vire e confira o interior","content":"Depois dos primeiros 20 minutos, vire com pinça e asse por mais 15 minutos a 220 °C. Meça várias peças grandes com sonda limpa na carne mais grossa, sem tocar osso nem grade: devem atingir pelo menos 74 °C. Se não atingirem, prolongue o forno e confira novamente antes de pincelar. Tamanho e forno mudam o tempo real; pele dourada não comprova segurança.","image_url":"/recetas/alitas-bbq/paso-05.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Vire e confira o interior"},{"title":"Pincele no final e deixe descansar","content":"Após conferir 74 °C nas asinhas, pincele uma camada fina da metade de molho destinada à cobertura. Volte ao forno a 220 °C por cerca de 5 minutos, cuidando para o açúcar não escurecer demais; grill não substitui cozimento. Confira novamente pelo menos 74 °C nas peças grossas, retire com luvas e descanse por 5 minutos. Propõem-se 40 minutos de forno mais esse descanso; qualquer cozimento adicional aumenta o total. Mantenha separado e limpo o molho reservado para servir.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Pincele no final e deixe descansar"},{"title":"Sirva em quatro porções","content":"Divida as asinhas quentes em 4 porções iguais, distribuindo peças grandes e pequenas, e acompanhe com o molho limpo reservado. A proposta soma 20 minutos de preparo, 40 de forno e 5 de descanso: 65 minutos totais, com preaquecimento e molho sobrepostos. Não houve teste de cozinha nem pesagem final. A nutrição supõe 700 g comestíveis de carne e pele para os 1000 g com osso, hipótese de 70 % a confirmar, e inclui todo o molho e azeite; isso não é o peso de cada porção.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Asinhas de frango BBQ no forno com molho de tomate: Sirva em quatro porções"}],"nutrition":{"calories":428.8,"protein_g":31.3,"carbs_g":18.7,"fat_g":25,"saturated_fat_g":6.6,"fiber_g":0.4,"sugar_g":14.9,"sodium_mg":837,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Asinhas de frango cruas com pele e osso, separadas, sem pontas","recipe_grams":1000,"edible_grams":700,"fdc_id":172390,"fdc_description":"Chicken, broilers or fryers, wing, meat and skin, raw","per_100g":{"calories":191,"protein_g":17.5,"carbs_g":0,"fat_g":12.8,"saturated_fat_g":3.54,"fiber_g":0,"sugar_g":0,"sodium_mg":84},"source_url":"https://fdc.nal.usda.gov/food-details/172390/nutrients"},{"ingredient":"Azeite de oliva","recipe_grams":10,"edible_grams":10,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"Sal fino","recipe_grams":3,"edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Pimenta-do-reino moída","recipe_grams":1,"edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"calories":251,"protein_g":10.4,"carbs_g":64,"fat_g":3.26,"saturated_fat_g":1.39,"fiber_g":25.3,"sugar_g":0.64,"sodium_mg":20},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"Ketchup de tomate","recipe_grams":160,"edible_grams":160,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"calories":101,"protein_g":1.04,"carbs_g":27.4,"fat_g":0.1,"saturated_fat_g":0.014,"fiber_g":0.3,"sugar_g":21.3,"sodium_mg":907},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"Açúcar mascavo","recipe_grams":25,"edible_grams":25,"fdc_id":168833,"fdc_description":"Sugars, brown","per_100g":{"calories":380,"protein_g":0.12,"carbs_g":98.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":97,"sodium_mg":28},"source_url":"https://fdc.nal.usda.gov/food-details/168833/nutrients"},{"ingredient":"Vinagre de maçã","recipe_grams":25,"edible_grams":25,"fdc_id":173469,"fdc_description":"Vinegar, cider","per_100g":{"calories":21,"protein_g":0,"carbs_g":0.93,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0.4,"sodium_mg":5},"source_url":"https://fdc.nal.usda.gov/food-details/173469/nutrients"},{"ingredient":"Molho Worcestershire","recipe_grams":10,"edible_grams":10,"fdc_id":171610,"fdc_description":"Sauce, worcestershire","per_100g":{"calories":77,"protein_g":0,"carbs_g":19.2,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":10,"sodium_mg":1300},"source_url":"https://fdc.nal.usda.gov/food-details/171610/nutrients"},{"ingredient":"Alho descascado bem picadinho","recipe_grams":8,"edible_grams":8,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"calories":149,"protein_g":6.36,"carbs_g":33.1,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sugar_g":1,"sodium_mg":17},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"Páprica doce defumada","recipe_grams":2,"edible_grams":2,"fdc_id":171329,"fdc_description":"Spices, paprika","per_100g":{"calories":282,"protein_g":14.1,"carbs_g":54,"fat_g":12.9,"saturated_fat_g":2.14,"fiber_g":34.9,"sugar_g":10.3,"sodium_mg":68},"source_url":"https://fdc.nal.usda.gov/food-details/171329/nutrients"},{"ingredient":"Água potável","recipe_grams":40,"edible_grams":40,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"}],"serving_size":"Um quarto das asinhas e de todo o molho proposto; 4 porções sem peso final medido","method":"Pondere onze quantidades comestíveis pelos oito valores USDA por 100 g, some e divida por 4. Para 1000 g com osso, use 700 g de carne e pele cruas comestíveis: hipótese de 70 % não medida nem atribuída a USDA. Inclui todo o azeite e molho sem descontar gordura escorrida ou restos.","note":"Estimativa de ingredientes, não análise nem teste de cozinha. A ficha do frango é para carne e pele cruas sem ossos; a fração suposta está a confirmar e varia por peça. Ketchup e Worcestershire genéricos, páprica defumada aproximada por páprica genérica. Marcas podem diferir. Peso cozido e molho consumido não medidos. Todos os oito nutrientes existem nas fichas; ausências não são preenchidas com zero."},"image_url":"/recetas/alitas-bbq/portada.webp","gallery":[{"url":"/recetas/alitas-bbq/portada.webp","alt":"Asinhas de frango assadas com cobertura vermelha BBQ de tomate ao lado de uma tigela de molho"}],"published":true,"editorial_status":"published","keywords":["asinhas BBQ","asinhas no forno","molho barbecue de tomate","asinhas com cobertura"],"notes":"Proposta editorial sem teste de cozinha. Asinhas com pele e osso sem pontas, já descongeladas; descongelamento fora dos tempos. Descongele na geladeira, mantenha a 4 °C ou menos e siga a embalagem. Não lave o frango cru; afaste seus sucos dos alimentos e utensílios limpos. Sonda na carne grossa, sem tocar osso, deve conferir pelo menos 74 °C; cor não basta. Esta BBQ de tomate, vinagre e açúcar mascavo é diferente de cobertura mel-shoyu; mel e shoyu não são acrescentados diretamente. Worcestershire pode conter peixe, glúten, soja ou outros alérgenos conforme a marca: confira os rótulos. O defumado vem da páprica, sem alegar cozimento em churrasqueira. Aplique açúcar no final e não amontoe. Ossos variam: o cálculo adota 700 g de carne e pele cruas comestíveis dos 1000 g com osso, 70 %, a confirmar com pesagem. Não é rendimento USDA nem resultado medido. Todo o azeite e molho são contados sem descontar gordura escorrida ou restos não consumidos; pode superestimar o consumo real. Páprica defumada modelada com páprica genérica e molhos variáveis por marca. Menos açúcar ou outro molho altera sabor, aderência e nutrição. Outra proteína exige cozimento e cálculo próprios. Refrigere logo as sobras em recipientes rasos a 4 °C ou menos e consuma em 3–4 dias conforme a orientação oficial para frango cozido. Não deixe fora mais de 2 horas, ou 1 hora acima de 32 °C. Reaqueça a 74 °C. Congelar porções tampadas por até 2 meses é uma proposta doméstica de qualidade, sem teste da textura desta fórmula.","seo":{"title":"Asinhas BBQ no forno com molho de tomate passo a passo","description":"Asinhas BBQ de tomate para quatro porções propostas. Cobertura final, tempos completos, conferência de 74 °C e nutrição estimada com fração comestível explícita.","image_alt":"Asinhas de frango assadas com cobertura vermelha BBQ de tomate ao lado de uma tigela de molho","image_variants":["/recetas/alitas-bbq/portada-1x1.webp","/recetas/alitas-bbq/portada-4x3.webp","/recetas/alitas-bbq/portada-16x9.webp"],"faq":[{"q":"As asinhas são feitas na churrasqueira?","a":"Esta proposta usa forno a 220 °C. BBQ descreve o molho de tomate, vinagre, açúcar mascavo e páprica defumada. Não se afirma defumação nem cozimento sobre brasas."},{"q":"Quando coloco o molho e confiro o frango?","a":"Confira primeiro pelo menos 74 °C no interior de várias peças grandes, sem tocar osso. Pincele o molho doce no final e asse cerca de 5 minutos, sem queimar. O tempo proposto não substitui o termômetro."},{"q":"O que entra na nutrição e como guardo sobras?","a":"Todo o molho e azeite, supondo 700 g comestíveis para 1000 g com osso: fração de 70 % não medida e a confirmar. Refrigere a 4 °C ou menos, consuma em 3–4 dias e reaqueça a 74 °C. Não deixe fora mais de 2 horas, ou 1 hora acima de 32 °C."}]},"content_html":"<p>Asinhas no forno com cobertura BBQ de tomate, açúcar mascavo, vinagre e páprica defumada aplicada no final. Propõem-se quatro porções e 65 minutos, com conferência de 74 °C no frango. Fórmula, rendimento e tempos aguardam teste de cozinha.</p><p>Proposta editorial sem teste de cozinha. Asinhas com pele e osso sem pontas, já descongeladas; descongelamento fora dos tempos. Descongele na geladeira, mantenha a 4 °C ou menos e siga a embalagem. Não lave o frango cru; afaste seus sucos dos alimentos e utensílios limpos. Sonda na carne grossa, sem tocar osso, deve conferir pelo menos 74 °C; cor não basta. Esta BBQ de tomate, vinagre e açúcar mascavo é diferente de cobertura mel-shoyu; mel e shoyu não são acrescentados diretamente. Worcestershire pode conter peixe, glúten, soja ou outros alérgenos conforme a marca: confira os rótulos. O defumado vem da páprica, sem alegar cozimento em churrasqueira. Aplique açúcar no final e não amontoe. Ossos variam: o cálculo adota 700 g de carne e pele cruas comestíveis dos 1000 g com osso, 70 %, a confirmar com pesagem. Não é rendimento USDA nem resultado medido. Todo o azeite e molho são contados sem descontar gordura escorrida ou restos não consumidos; pode superestimar o consumo real. Páprica defumada modelada com páprica genérica e molhos variáveis por marca. Menos açúcar ou outro molho altera sabor, aderência e nutrição. Outra proteína exige cozimento e cálculo próprios. Refrigere logo as sobras em recipientes rasos a 4 °C ou menos e consuma em 3–4 dias conforme a orientação oficial para frango cozido. Não deixe fora mais de 2 horas, ou 1 hora acima de 32 °C. Reaqueça a 74 °C. Congelar porções tampadas por até 2 meses é uma proposta doméstica de qualidade, sem teste da textura desta fórmula.</p>"}]$records$::jsonb;
